            {let node=self.kernel.nodes.get(&id).unwrap();if matches!(node.value(),TreeNode::Leaf(_)){catalog.mark(self.kernel.node_owner(id,true),id)?;}}
            let (_,mut node)=self.kernel.nodes.remove(&id).unwrap();let owner=self.kernel.node_owner(id,matches!(node,TreeNode::Leaf(_)));
            let centroid=self.kernel.node_centroid(id,node.centroid());let code=self.kernel.quantize_origin(&centroid);
