    async fn placement_catalog_no_feasible_move_and_destination_capacity(){for exhausted in [false,true]{let dir=tempfile::tempdir().unwrap();let p=provider(dir.path());let mut writer=WideOwnerWriter::new(32,DistanceFunction::Euclidean,config(),2,&[0],64,p.clone(),super::super::super::owner_vector_store::VectorLimits::default()).unwrap();writer.enable_dirty_scheduler(p.clone(),super::super::owner_work_queue::Limits{cache_pages_per_home:1,max_active_pages:4096}).unwrap();writer.enable_full_records_with_placement(p.clone(),super::super::super::owner_node_access::Limits::default(),super::super::super::owner_placement_catalog::Limits{cache_pages_per_owner:1,active_pages_per_owner:2,pages_per_phase:2,moves_per_phase:1}).unwrap();let input:Vec<_>=(0..4u64).map(|id|(id,vec![id as f32;32])).collect();writer.add_phase(&input,1).unwrap();writer.balance_phase(1).unwrap();let saved=writer.save(&p).await.unwrap();let mut old=Reader64::open(&p,saved,32).await.unwrap();let census=old.census().await.unwrap();if exhausted{let catalog=writer.kernel.owner_placement.as_ref().unwrap().clone();catalog.mark(1,64).unwrap();catalog.mark(1,128).unwrap();assert!(writer.move_leaf(0,1).is_err());assert!(writer.failed);assert_eq!(writer.backend().located_owner(0),Some(0));assert_eq!(writer.backend().actors[0].call(|state|state.current.read().len()),4);assert_eq!(writer.backend().actors[1].call(|state|state.current.read().len()),0);assert!(writer.save(&p).await.is_err());}else{assert_eq!(writer.redistribute_current(1).unwrap(),0);assert_eq!(writer.placement_report["unfinished_skew"],true);assert_eq!(writer.placement_report["no_feasible_move_in_admitted_pages"],true);assert!(!writer.failed);}assert!(writer.kernel.nodes.is_empty()&&writer.backend().leaf_owner.is_empty());assert_eq!(old.census().await.unwrap(),census);println!("PLACEMENT_TERMINAL {}",serde_json::json!({"capacity_exhausted":exhausted,"phase":writer.placement_report,"rows":4}));}}
